function boneDensity(t){
  t=+t; if(isNaN(t)) return {error:'T 值须为数字'};
  var level = t>=-1?'正常':(t>=-2.5?'骨量减少（骨质疏松前期）':'骨质疏松');
  return {t:t, level:level};
}
var EXPORTS={boneDensity:boneDensity};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BoneForgePure = EXPORTS; }
